//   ningún secreto y funciona igual en cualquier entorno.
// * `this.helpers.httpRequest` es la forma que n8n da a un nodo Code para llamar a un servicio.

const http = (opciones) => this.helpers.httpRequest({ json: true, ignoreHttpStatusErrors: true, ...opciones });

const API_WHATSAPP = ($env.WHATSAPP_API_URL || 'https://graph.facebook.com/v21.0').replace(/\/$/, '');

/** Llama a una ruta interna de Identidad con la credencial de servicio. Devuelve { estado, cuerpo }. */
async function identidad(ruta, cuerpo) {
  const respuesta = await http({
    method: 'POST',
    url: `${$env.IDENTIDAD_URL.replace(/\/$/, '')}${ruta}`,
    headers: { 'X-Service-Key': $env.IDENTIDAD_CREDENCIAL_N8N },
    body: cuerpo,
    returnFullResponse: true,
    timeout: 10000,
  });
  return { estado: respuesta.statusCode, cuerpo: respuesta.body || {} };
}

/** Un mensaje de texto para WhatsApp, listo para enviar. */
function texto(para, cuerpo) {
  return {
    json: {
      mensaje: {
        messaging_product: 'whatsapp',
        to: para,
        type: 'text',
        text: { body: String(cuerpo).slice(0, 4000), preview_url: true },
      },
    },
  };
}

/** Un mensaje con hasta 3 botones: lista = [[id, título], ...]. El título admite 20 caracteres. */
function botones(para, cuerpo, lista) {
  return {
    json: {
      mensaje: {
        messaging_product: 'whatsapp',
        to: para,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: String(cuerpo).slice(0, 1000) },
          action: {
            buttons: lista.slice(0, 3).map(([id, titulo]) => ({
              type: 'reply',
              reply: { id: String(id).slice(0, 256), title: String(titulo).slice(0, 20) },
            })),
          },
        },
      },
    },
  };
}

// ¿De quién es este número? Le pide a Identidad una sesión corta (5 minutos) del estudiante vinculado.
//  - 200: el número está vinculado -> `modo: 'agente'` y el token para hablar con el servidor MCP.
//  - 404 (ERR_IDE_26): nadie lo vinculó -> `modo: 'acceso'` (iniciar sesión o registrarse).
//  - 403 (ERR_IDE_27): la cuenta ya no puede usar el chat -> se le avisa y no se sigue.
//  - cualquier otra cosa: Identidad no responde -> se le pide reintentar; nunca se muestra el detalle.
const salida = [];
for (const item of $input.all()) {
  const mensaje = item.json;

  // Fotos, notas de voz, documentos...: por ahora solo se entiende texto, botones y la ubicación del registro
  if (!mensaje.texto && !mensaje.botonId && mensaje.latitud === null) {
    salida.push({
      json: {
        ...mensaje,
        modo: 'aviso',
        ...texto(mensaje.telefono, 'Por ahora solo entiendo mensajes de texto. Escríbeme lo que necesitas.').json,
      },
    });
    continue;
  }

  let respuesta;
  try {
    respuesta = await identidad('/internal/v1/whatsapp/sesiones', { telefono: mensaje.telefono });
  } catch (e) {
    respuesta = { estado: 0, cuerpo: {} };
  }

  if (respuesta.estado === 200 && respuesta.cuerpo.data) {
    salida.push({ json: { ...mensaje, modo: 'agente', accessToken: respuesta.cuerpo.data.accessToken } });
  } else if (respuesta.estado === 404) {
    salida.push({ json: { ...mensaje, modo: 'acceso' } });
  } else if (respuesta.estado === 403) {
    salida.push({
      json: {
        ...mensaje,
        modo: 'aviso',
        ...texto(
          mensaje.telefono,
          'Tu cuenta no puede usar este chat. Comunícate con tu autoescuela para revisar tu cuenta.'
        ).json,
      },
    });
  } else {
    salida.push({
      json: {
        ...mensaje,
        modo: 'aviso',
        ...texto(mensaje.telefono, 'No pude atenderte ahora. Inténtalo de nuevo en unos minutos.').json,
      },
    });
  }
}
return salida;

